                Json(json!({"delivered":false, "detail":detail})),
            )
                .into_response();
        }
        Err(_) => {
            return (
                axum::http::StatusCode::SERVICE_UNAVAILABLE,
                Json(json!({"delivered":false, "detail":"speech worker stopped"})),
            )
                .into_response();
        }
    }
}

